using System;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.IO;using System.Collections.Generic;
class TavernHallVisualChecks {
 static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var v in All(child))yield return v;}
 static void Pump(int milliseconds){var end=DateTime.UtcNow.AddMilliseconds(milliseconds);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(5);}}
 [STAThread]static void Main(){try{Run();}catch(Exception e){Console.WriteLine(e);Environment.Exit(1);}}
 static void Run(){string root=AppDomain.CurrentDomain.BaseDirectory;var flags=BindingFlags.NonPublic|BindingFlags.Instance;foreach(var name in new[]{"aelia-actions.png","lyse-actions.png","guest-actions.png","luchuan-actions.png","rest-actions.png","delivery-walk.png"})using(var art=new Bitmap(Path.Combine(root,"assets/tavern/management/actions",name))){Check(art.GetPixel(0,0).A==0,"transparent alpha: "+name);Check(art.Width/4f>=200,"readable four frame cells");}Check(HallActionRows.Server("收桌",5)==2&&HallActionRows.Server("收桌",7)==3,"wipe then stack dishes");Check(HallActionRows.Guest(new HallGuest{stage=4,recipe=0})==1&&HallActionRows.Guest(new HallGuest{stage=4,recipe=3})==2,"eat soup vs drink");
 using(var subtitle=new HallSentencePanel{Width=1240,Height=210}){Check(subtitle.English.Font.Size==18,"English subtitle matches main-story dialogue size");Check(subtitle.Chinese.Font.Size==subtitle.English.Font.Size,"Chinese and English subtitles have equal font size");string en="Even so, there have been a very small number of cases recently when authorities have discovered eggs during further inspections.";subtitle.SetSentence(en,"即便如此，最近仍有极少数情况下，当局在进一步检查时发现了鸡蛋。",true,true);Check(subtitle.PageCount==1&&subtitle.English.Text==en,"two-line English fits without a premature pager");Check(subtitle.English.Height>=8+subtitle.English.WrappedLineCount(subtitle.English.Width-22)*(int)Math.Ceiling(subtitle.English.Font.Height*1.55),"all wrapped English lines remain visible");subtitle.Width=300;subtitle.SetSentence(String.Join(" ",Enumerable.Repeat(en,3)),"中文",true,true);Check(subtitle.PageCount>1,"genuinely oversized captions stay accessible");} using(var kitchen=Image.FromFile(Path.Combine(root,"chapters/art/tavern/chapter-one-kitchen.png")))using(var canvas=new TavernHallCanvas{KitchenArt=kitchen,Width=1400,Height=1132,State=TavernHall.State(new Save()),Guiding=true})using(var art=Image.FromFile(Path.Combine(root,"assets/tavern/management/hall-empty.png")))using(var shot=new Bitmap(1400,1132)){using(var baseline=new Bitmap(1400,1132)){using(var bg=Graphics.FromImage(baseline)){bg.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;bg.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;bg.DrawImage(art,0,0,1400,1132);}canvas.Art=art;canvas.LoadWalking(Path.Combine(root,"assets/tavern/management"));canvas.State.guests.Add(new HallGuest{id=1,table=0,stage=4,recipe=0});canvas.DrawToBitmap(shot,new Rectangle(0,0,1400,1132));using(var path=new System.Drawing.Drawing2D.GraphicsPath()){path.AddPolygon(HallFurniture.BarFront);int visible=0;for(int y=450;y<610;y++)for(int x=875;x<995;x++){if(path.IsVisible(x,y))Check(shot.GetPixel(x,y)==baseline.GetPixel(x,y),"bar foreground fully hides lower body at "+x+","+y+" art="+art.Size+" colors="+shot.GetPixel(x,y)+"/"+baseline.GetPixel(x,y));else if(shot.GetPixel(x,y)!=baseline.GetPixel(x,y))visible++;}Check(visible>100,"owner upper body remains visible above counter");}Check(shot.GetPixel(544,602)==baseline.GetPixel(544,602),"chair front rail occludes seated legs");shot.Save(Path.Combine(root,"management-perspective-detail.png"));}} using(var game=new Game()){typeof(Game).GetField("save",flags).SetValue(game,new Save());game.Size=new Size(1100,740);game.Location=new Point(10,10);game.Show();typeof(Game).GetMethod("ShowTavernHall",flags).Invoke(game,null);Pump(200);var scene=All(game).OfType<TavernHallCanvas>().Single();var state=scene.State;state.guests.Add(new HallGuest{id=1,table=0,stage=4,recipe=0});state.guests.Add(new HallGuest{id=2,table=1,stage=4,recipe=3});state.guests.Add(new HallGuest{id=3,table=2,stage=6});state.guests.Add(new HallGuest{id=4,table=3,stage=1});state.server.job=3;state.server.action="收桌";state.server.progress=5;state.chef.action="切配";All(game).OfType<VNButton>().First(b=>b.Text=="暂停").PerformClick();for(int i=0;i<110;i++){scene.Animation=i*.08;scene.Invalidate();scene.Update();}using(var shot=new Bitmap(game.Width,game.Height)){game.DrawToBitmap(shot,new Rectangle(Point.Empty,game.Size));shot.Save(Path.Combine(root,"management-actions.png"));}
 // A stable subtitle must remain stable while the scene keeps requesting repaints.
 var overlay=(HallDialogueOverlay)typeof(Game).GetField("hallDialogue",flags).GetValue(game);overlay.Visible=true;var sentence=new HallSentencePanel{Dock=DockStyle.Fill,BackColor=Color.Transparent};sentence.English.BackColor=Color.Transparent;sentence.English.Shadow=true;sentence.SetSentence("The staff prepare meals and clean the tables.","员工准备餐点并收拾餐桌。",true,true);overlay.Controls.Add(sentence);overlay.BringToFront();Pump(300);var cp=(CreateParams)typeof(TavernHallCanvas).GetProperty("CreateParams",flags).GetValue(scene,null);Check((cp.ExStyle&0x02000000)!=0,"scene and translucent children composited together");Point origin=overlay.PointToScreen(new Point(20,20));using(var first=new Bitmap(overlay.Width-40,overlay.Height-40)){using(var g=Graphics.FromImage(first))g.CopyFromScreen(origin,Point.Empty,first.Size);for(int frame=0;frame<24;frame++){scene.Invalidate();Application.DoEvents();using(var current=new Bitmap(first.Width,first.Height)){using(var g=Graphics.FromImage(current))g.CopyFromScreen(origin,Point.Empty,current.Size);int changed=0,total=0;for(int y=6;y<first.Height;y+=9)for(int x=6;x<first.Width;x+=9){total++;if(first.GetPixel(x,y)!=current.GetPixel(x,y))changed++;}Check(changed<total*.03,"subtitle pixels do not flash or clear on scene repaint");}System.Threading.Thread.Sleep(10);}}using(var shot=new Bitmap(game.Width,game.Height)){game.DrawToBitmap(shot,new Rectangle(Point.Empty,game.Size));shot.Save(Path.Combine(root,"management-subtitle-stability.png"));}game.Close();}Console.WriteLine("PASS visual: generated action alpha/state mapping, sitting/eating/cleaning preview, composited subtitle stable across 24 live screen captures");}
}
